changeSet.sql:
ALTER TABLE zc_role_assignment
  ADD CONSTRAINT fk_zc_role_assignment_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_role_assignment
  ADD CONSTRAINT fk_zc_role_assignment_organisation FOREIGN KEY (tenant_id, organisation_id)
    REFERENCES zc_organisation (tenant_id, id);

ALTER TABLE zc_user
  ADD CONSTRAINT fk_zc_user_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
-- Org must be in the same tenant.
ALTER TABLE zc_user
  ADD CONSTRAINT fk_zc_user_org FOREIGN KEY (tenant_id, org) REFERENCES zc_organisation (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_organisation ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_organisation FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_organisation_tenant ON zc_organisation
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_role_assignment ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_role_assignment FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_role_assignment_tenant ON zc_role_assignment
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_break_glass_grant ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_break_glass_grant FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_break_glass_grant_tenant ON zc_break_glass_grant
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_config_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_config_history FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_config_history_tenant ON zc_config_history
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_organisation_tenant ON zc_organisation;
ALTER TABLE zc_organisation NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_organisation DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_role_assignment_tenant ON zc_role_assignment;
ALTER TABLE zc_role_assignment NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_role_assignment DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_break_glass_grant_tenant ON zc_break_glass_grant;
ALTER TABLE zc_break_glass_grant NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_break_glass_grant DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_config_history_tenant ON zc_config_history;
ALTER TABLE zc_config_history NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_config_history DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT ON zc_tenant TO zc_app;
GRANT SELECT ON zc_tenant TO zc_housekeeping;
GRANT USAGE ON SEQUENCE zc_tenant_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_organisation TO zc_app;
GRANT USAGE ON SEQUENCE zc_organisation_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_role_assignment TO zc_app;
GRANT USAGE ON SEQUENCE zc_role_assignment_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_break_glass_grant TO zc_app;
GRANT USAGE ON SEQUENCE zc_break_glass_grant_id_seq TO zc_app;
GRANT SELECT, INSERT ON zc_config_history TO zc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON zc_config_history FROM zc_app;
GRANT USAGE ON SEQUENCE zc_config_history_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_user TO zc_app;
GRANT USAGE ON SEQUENCE zc_user_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_tenant_whatsapp TO zc_app;

rollback.sql:
REVOKE ALL ON zc_tenant FROM zc_app, zc_housekeeping;
REVOKE USAGE ON SEQUENCE zc_tenant_id_seq FROM zc_app;
REVOKE ALL ON zc_organisation FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_organisation_id_seq FROM zc_app;
REVOKE ALL ON zc_role_assignment FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_role_assignment_id_seq FROM zc_app;
REVOKE ALL ON zc_break_glass_grant FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_break_glass_grant_id_seq FROM zc_app;
REVOKE ALL ON zc_config_history FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_config_history_id_seq FROM zc_app;
REVOKE ALL ON zc_user FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_user_id_seq FROM zc_app;
REVOKE ALL ON zc_tenant_whatsapp FROM zc_app;
